def to_24_hour(time_str):
    time_part, period = time_str.split(' ')
    h, m = time_part.split(':')
    h = int(h)
    if period == 'AM':
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12
    return f'{h:02d}:{m}'

def round_to_nearest_minutes(time_str, step):
    h, m = time_str.split(':')
    total = int(h) * 60 + int(m)
    remainder = total % step
    if remainder * 2 >= step:
        total += (step - remainder)
    else:
        total -= remainder
    total %= 1440
    return f'{total // 60:02d}:{total % 60:02d}'

def earlier_time(t1, t2):
    def to_minutes(t):
        h, m = t.split(':')
        return int(h) * 60 + int(m)

    if to_minutes(t2) < to_minutes(t1):
        return t2
    return t1

def meeting_overlap_minutes(s1, e1, s2, e2):
    start = max(s1, s2)
    end = min(e1, e2)
    return max(0, end - start)

def merged_busy_minutes(intervals):
    if not intervals:
        return 0
    sorted_intervals = sorted(intervals)
    total = 0
    cur_start, cur_end = sorted_intervals[0]
    for s, e in sorted_intervals[1:]:
        if s <= cur_end:
            cur_end = max(cur_end, e)
        else:
            total += cur_end - cur_start
            cur_start, cur_end = s, e
    total += cur_end - cur_start
    return total

def free_time_slots(intervals, day_start, day_end):
    slots = []
    cur = day_start
    for s, e in intervals:
        if s > cur:
            slots.append((cur, s))
        cur = max(cur, e)
    if cur < day_end:
        slots.append((cur, day_end))
    return slots

def previous_leap_year(year):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    y = year - 1
    while not is_leap(y):
        y -= 1
    return y

def leap_years_before(year):
    y = year - 1
    if y < 1:
        return 0
    return y // 4 - y // 100 + y // 400

def day_count_since_epoch(year, month, day):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def ordinal(y, m, d):
        doy = sum(days_in_month[:m - 1])
        if is_leap(y) and m > 2:
            doy += 1
        doy += d
        yy = y - 1
        leap_count = yy // 4 - yy // 100 + yy // 400
        return yy * 365 + leap_count + doy

    return ordinal(year, month, day) - ordinal(1970, 1, 1)

def date_from_epoch_days(n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_year_(y):
        return 366 if is_leap(y) else 365

    def days_in_month_(y, m):
        dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return dim[m - 1]

    year = 1970
    remaining = n
    if remaining >= 0:
        while remaining >= days_in_year_(year):
            remaining -= days_in_year_(year)
            year += 1
    else:
        while remaining < 0:
            year -= 1
            remaining += days_in_year_(year)
    month = 1
    while remaining >= days_in_month_(year, month):
        remaining -= days_in_month_(year, month)
        month += 1
    day = remaining + 1
    return (year, month, day)

def last_day_of_month(year, month):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return (year, month, dim[month - 1])

def previous_month(year, month):
    if month == 1:
        return (year - 1, 12)
    return (year, month - 1)

def add_months(year, month, n):
    total = (year * 12 + (month - 1)) + n
    new_year = total // 12
    new_month = total % 12 + 1
    return (new_year, new_month)

def weekday_name_from_index(index):
    names = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
    return names[index % 7]
